"use client"

import * as React from "react"
import { Toast as ToastPrimitive } from "@base-ui/react/toast"

import {
  Toast,
  ToastClose,
  ToastDescription,
  ToastProvider,
  ToastTitle,
  ToastViewport,
} from "./toast"
import {
  TOAST_LIMIT,
  syncFromManager,
  toastManager,
  type ToastData,
} from "./use-toast"

/** Renders every live toast from the shared manager. */
function ToastList() {
  const { toasts } = ToastPrimitive.useToastManager()

  // Removals that happen inside the provider (timeout, swipe, the close
  // button) flow back to the use-toast store, so useToast().toasts stays true.
  React.useEffect(() => {
    syncFromManager(toasts)
  }, [toasts])

  return (
    <>
      {toasts
        .filter((toastObject) => !toastObject.limited)
        .map(function (toastObject) {
          const { id, title, description, data } = toastObject
          // SAFETY: `data` is what use-toast stored on this toast, so it has
          // the ToastData shape written on the way in.
          const { action, rootProps } = (data ?? {}) as Partial<ToastData>
          return (
            <Toast key={id} toast={toastObject} {...rootProps}>
              <div className="grid gap-0.5">
                {title && <ToastTitle>{title}</ToastTitle>}
                {description && (
                  <ToastDescription>{description}</ToastDescription>
                )}
              </div>
              {action}
              <ToastClose />
            </Toast>
          )
        })}
    </>
  )
}

/** Margin Toaster: mount it once near the root to show the toasts that useToast() raises. */
export function Toaster() {
  return (
    <ToastProvider toastManager={toastManager} limit={TOAST_LIMIT}>
      <ToastViewport>
        <ToastList />
      </ToastViewport>
    </ToastProvider>
  )
}
